/* ---------------------------------------------------------------
   Menu data
--------------------------------------------------------------- */
const TEMPS_STANDARD = [
  { id: "hot", en: "Hot" },
  { id: "ice", en: "Iced" },
  { id: "lightice", en: "Light Ice" },
  { id: "noice", en: "No Ice" },
];
const TEMPS_ESPRESSO = [...TEMPS_STANDARD, { id: "coldbrew", en: "Cold Brew" }];

const FLAVORS = [
  { id: "original", en: "Original (No Flavor)" },
  { id: "misobanana", en: "Toasted Miso Banana" },
  { id: "strawberry", en: "Strawberry" },
  { id: "blacksesame", en: "Black Sesame" },
];

const BASES = [
  { id: "water", en: "Americano Style (Water)" },
  { id: "coconut", en: "Coconut Water" },
  { id: "oat", en: "Oat Milk" },
  { id: "whole", en: "Whole Milk" },
  { id: "lactaid", en: "Lactaid Milk" },
];

const DRINKS = [
  {
    id: "matcha", en: "Matcha", verb: "whisking",
    note: "Stone-ground, whisked to order.",
    temps: TEMPS_STANDARD, flavors: FLAVORS, bases: BASES,
    foamEligible: (d) => d.flavor !== "original",
  },
  {
    id: "espresso", en: "Espresso", verb: "brewing",
    note: "Double shot, house blend.",
    temps: TEMPS_ESPRESSO, flavors: FLAVORS, bases: BASES,
    foamEligible: (d) => d.flavor !== "original" || d.temp === "coldbrew",
  },
  {
    id: "pourover", en: "Pour Over", verb: "pouring",
    note: "Single origin, brewed slow.",
    special: true,
  },
];

const DEFAULT_DRAFT = { temp: "hot", flavor: "original", base: "water", foam: false };

function describeItem(item) {
  if (item.drinkId === "pourover") return "Ask about today's beans";
  const parts = [];
  const t = TEMPS_ESPRESSO.find((x) => x.id === item.temp);
  if (t) parts.push(t.en);
  if (item.flavor && item.flavor !== "original") {
    const f = FLAVORS.find((x) => x.id === item.flavor);
    if (f) parts.push(f.en);
  }
  const b = BASES.find((x) => x.id === item.base);
  if (b) parts.push(b.en);
  if (item.foam) parts.push("Cold Foam");
  return parts.length ? parts.join(" - ") : "Plain";
}

function primaryDrink(cart) {
  if (cart.length === 0) return DRINKS[0];
  const counts = {};
  cart.forEach((i) => (counts[i.drinkId] = (counts[i.drinkId] || 0) + 1));
  let best = cart[0].drinkId, bestCount = 0;
  cart.forEach((i) => { if (counts[i.drinkId] > bestCount) { bestCount = counts[i.drinkId]; best = i.drinkId; } });
  return DRINKS.find((d) => d.id === best) || DRINKS[0];
}

