/* ---------------------------------------------------------------
   Main app
--------------------------------------------------------------- */
export default function HalfDayCafe() {
  const [page, setPage] = useState("home");
  const [cart, setCart] = useState([]);
  const [draft, setDraft] = useState(DEFAULT_DRAFT);
  const [customerName, setCustomerName] = useState("");
  const [orderNumber, setOrderNumber] = useState(null);
  const [submitError, setSubmitError] = useState(null);
  const keyCounter = useRef(0);

  const [orders, setOrders] = useState([]);
  const [queueLoading, setQueueLoading] = useState(true);
  const [queueError, setQueueError] = useState(null);
  const [selectedItem, setSelectedItem] = useState(null); // { orderRowId, orderNumber, name, item, itemIndex }
  const [resetArm, setResetArm] = useState(false);
  const [resetMsg, setResetMsg] = useState(null);
  const [baristaView, setBaristaView] = useState("queue"); // queue | history
  const [history, setHistory] = useState([]);
  const [historyLoading, setHistoryLoading] = useState(true);
  const [historyError, setHistoryError] = useState(null);

  const loadHistory = useCallback(async () => {
    try {
      const data = await fetchOrderHistory();
      setHistory(data);
      setHistoryError(null);
    } catch (err) { setHistoryError(friendlyError(err)); }
    setHistoryLoading(false);
  }, []);

  useEffect(() => {
    if (page !== "barista" || baristaView !== "history") return;
    loadHistory();
  }, [page, baristaView, loadHistory]);

  const loadQueue = useCallback(async () => {
    try {
      const data = await fetchActiveOrders();
      setOrders(data);
      setQueueError(null);
    } catch (err) { setQueueError(friendlyError(err)); }
    setQueueLoading(false);
  }, []);

  useEffect(() => {
    if (page !== "barista") return;
    loadQueue();
    const id = setInterval(loadQueue, 3000);
    return () => clearInterval(id);
  }, [page, loadQueue]);

  useEffect(() => {
    if (!resetArm) return;
    const t = setTimeout(() => setResetArm(false), 4000);
    return () => clearTimeout(t);
  }, [resetArm]);

  const stationItems = (drinkId) => {
    const list = [];
    orders.forEach((o) => {
      (o.items || []).forEach((it, idx) => {
        if (it.drinkId === drinkId && it.status !== "ready") {
          list.push({ orderRowId: o.id, orderNumber: o.number, name: o.name, item: it, itemIndex: idx, createdAt: o.created_at });
        }
      });
    });
    list.sort((a, b) => new Date(a.createdAt) - new Date(b.createdAt));
    return list;
  };

  const markItemReady = async (entry) => {
    const order = orders.find((o) => o.id === entry.orderRowId);
    if (!order) return;
    const newItems = order.items.map((it, idx) => (idx === entry.itemIndex ? { ...it, status: "ready" } : it));
    const allReady = newItems.every((it) => it.status === "ready");
    try {
      await withRetry(() => updateOrderItems(entry.orderRowId, newItems, allReady ? "done" : "pending"));
      setOrders((prev) => prev.map((o) => (o.id === entry.orderRowId ? { ...o, items: newItems, status: allReady ? "done" : "pending" } : o)));
      setSelectedItem(null);
    } catch (err) {
      setQueueError(friendlyError(err));
    }
  };

  const doResetCounter = async () => {
    try {
      await withRetry(resetOrderCounterDb);
      setResetMsg("Counter reset to 00.");
      setResetArm(false);
      setTimeout(() => setResetMsg(null), 3000);
    } catch (err) {
      setResetMsg(friendlyError(err));
    }
  };

  const openDrink = (id) => { setDraft(DEFAULT_DRAFT); setPage(id); };

  const addToCart = (drink) => {
    keyCounter.current += 1;
    const foamOk = drink.foamEligible ? drink.foamEligible(draft) : false;
    const base = drink.special
      ? { key: keyCounter.current, drinkId: drink.id, en: drink.en, status: "pending" }
      : { key: keyCounter.current, drinkId: drink.id, en: drink.en, temp: draft.temp, flavor: draft.flavor, base: draft.base, foam: foamOk ? draft.foam : false, status: "pending" };
    setCart((c) => [...c, base]);
    setPage("home");
  };

  const removeFromCart = (key) => setCart((c) => c.filter((i) => i.key !== key));

  const submitOrder = async () => {
    if (cart.length === 0 || !customerName.trim()) return;
    setSubmitError(null);
    setPage("submitting");
    try {
      const number = await withRetry(reserveOrderNumber);
      await withRetry(() => insertOrder({ number, name: customerName.trim(), items: cart.map(({ key, ...rest }) => rest) }));
      setOrderNumber(number);
      setPage("confirmed");
    } catch (err) {
      setSubmitError(friendlyError(err));
      setPage("cart");
    }
  };

  const newOrder = () => { setCart([]); setOrderNumber(null); setCustomerName(""); setSubmitError(null); setPage("home"); };

  const primary = primaryDrink(cart);
  const currentDrink = DRINKS.find((d) => d.id === page);

  /* ---------------- Barista ---------------- */
  if (page === "barista") {
    const stations = [
      { id: "matcha", label: "Matcha Station" },
      { id: "espresso", label: "Espresso Station" },
      { id: "pourover", label: "Pour Over Station" },
    ];
    return (
      <div className="hd-ui" style={{ minHeight: "100vh", width: "100%", color: COLORS.cream, position: "relative" }}>
        <GlobalStyle /><SketchyDefs />
        <BackgroundPhoto src={BG.home} />
        <div style={{ position: "relative", paddingBottom: "110px" }}>
          <div style={{ padding: "50px 22px 16px" }}>
            <div className="hd-display" style={{ fontSize: "28px", fontWeight: 600, color: COLORS.white }}>Barista</div>
            <div style={{ fontSize: "12px", color: "rgba(244,240,230,0.7)" }}>Half Day Cafe - tap an item to see details and mark it ready</div>
            <div style={{ display: "flex", gap: "8px", marginTop: "14px" }}>
              <button onClick={() => setBaristaView("queue")} style={{ padding: "7px 14px", borderRadius: "999px", border: `1px solid ${baristaView === "queue" ? COLORS.gold : COLORS.line}`, background: baristaView === "queue" ? "rgba(201,168,118,0.2)" : "rgba(4,12,8,0.4)", color: COLORS.cream, fontSize: "12px", fontWeight: 600, cursor: "pointer" }}>
                Queue
              </button>
              <button onClick={() => setBaristaView("history")} style={{ padding: "7px 14px", borderRadius: "999px", border: `1px solid ${baristaView === "history" ? COLORS.gold : COLORS.line}`, background: baristaView === "history" ? "rgba(201,168,118,0.2)" : "rgba(4,12,8,0.4)", color: COLORS.cream, fontSize: "12px", fontWeight: 600, cursor: "pointer" }}>
                History
              </button>
            </div>
          </div>

          {baristaView === "history" ? (
            <div style={{ padding: "0 22px" }}>
              {historyError && <div style={{ fontSize: "12.5px", color: "#f4b48a", marginBottom: "14px" }}>{historyError}</div>}
              {historyLoading ? (
                <div style={{ color: "rgba(244,240,230,0.7)", fontSize: "13px" }}>Loading history...</div>
              ) : history.length === 0 ? (
                <div style={{ color: "rgba(244,240,230,0.55)", fontSize: "13px", marginTop: "40px", textAlign: "center" }}>No completed orders yet.</div>
              ) : (
                <>
                  <div style={{ fontSize: "12px", color: "rgba(244,240,230,0.6)", marginBottom: "12px" }}>{history.length} completed order{history.length === 1 ? "" : "s"} (most recent 200)</div>
                  <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
                    {history.map((o) => (
                      <div key={o.id} style={{ borderRadius: "14px", border: `1px solid ${COLORS.line}`, background: "rgba(4,12,8,0.45)", padding: "12px 14px" }}>
                        <div style={{ display: "flex", alignItems: "baseline", gap: "10px" }}>
                          <div className="hd-display" style={{ fontSize: "20px", fontWeight: 600, color: COLORS.gold }}>{formatOrderNumber(o.number)}</div>
                          {o.name && <div style={{ fontSize: "12.5px", color: COLORS.white, fontWeight: 600 }}>{o.name}</div>}
                          <div style={{ fontSize: "10.5px", color: "rgba(244,240,230,0.45)", marginLeft: "auto" }}>{new Date(o.created_at).toLocaleString()}</div>
                        </div>
                        <div style={{ marginTop: "6px", display: "flex", flexDirection: "column", gap: "2px" }}>
                          {(o.items || []).map((it, i) => (
                            <div key={i} style={{ fontSize: "11.5px", color: "rgba(244,240,230,0.65)" }}>{it.en} - {describeItem(it)}</div>
                          ))}
                        </div>
                      </div>
                    ))}
                  </div>
                </>
              )}
            </div>
          ) : (
          <>
          {queueError && <div style={{ margin: "0 22px 14px", fontSize: "12.5px", color: "#f4b48a" }}>{queueError}</div>}

          {queueLoading ? (
            <div style={{ padding: "0 22px", color: "rgba(244,240,230,0.7)", fontSize: "13px" }}>Loading queue...</div>
          ) : (
            <div style={{ padding: "0 16px", display: "flex", flexDirection: "column", gap: "18px" }}>
              {stations.map((st) => {
                const items = stationItems(st.id);
                return (
                  <div key={st.id}>
                    <div style={{ display: "flex", alignItems: "center", gap: "8px", padding: "0 6px 8px" }}>
                      <div style={{ width: 26, height: 26, borderRadius: "50%", background: COLORS.cream, display: "flex", alignItems: "center", justifyContent: "center" }}>
                        <DrinkIcon type={st.id} size={16} />
                      </div>
                      <div className="hd-display" style={{ fontSize: "18px", fontWeight: 600, color: COLORS.white }}>{st.label}</div>
                      <div style={{ fontSize: "11px", color: "rgba(244,240,230,0.55)" }}>{items.length} pending</div>
                    </div>
                    {items.length === 0 ? (
                      <div style={{ fontSize: "12px", color: "rgba(244,240,230,0.4)", padding: "0 6px 4px" }}>Nothing waiting.</div>
                    ) : (
                      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(120px, 1fr))", gap: "10px" }}>
                        {items.map((entry) => (
                          <button
                            key={`${entry.orderRowId}-${entry.itemIndex}`}
                            onClick={() => setSelectedItem(entry)}
                            className="hd-card-btn"
                            style={{ textAlign: "left", borderRadius: "14px", border: `1px solid ${COLORS.line}`, background: "rgba(4,12,8,0.55)", backdropFilter: "blur(10px)", padding: "12px", cursor: "pointer", color: COLORS.cream }}
                          >
                            <div className="hd-display" style={{ fontSize: "24px", fontWeight: 600, color: COLORS.gold, lineHeight: 1 }}>{formatOrderNumber(entry.orderNumber)}</div>
                            {entry.name && <div style={{ fontSize: "12px", color: COLORS.white, fontWeight: 600, marginTop: "4px" }}>{entry.name}</div>}
                            <div style={{ fontSize: "10.5px", color: "rgba(244,240,230,0.6)", marginTop: "4px" }}>Tap for details</div>
                          </button>
                        ))}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          )}

          {/* testing tools */}
          <div style={{ margin: "26px 22px 0", paddingTop: "16px", borderTop: `1px solid ${COLORS.line}` }}>
            <div style={{ fontSize: "10.5px", letterSpacing: "0.08em", color: "rgba(244,240,230,0.4)", marginBottom: "8px", fontWeight: 700 }}>TESTING</div>
            <button
              onClick={() => (resetArm ? doResetCounter() : setResetArm(true))}
              style={{ padding: "9px 14px", borderRadius: "999px", border: `1px solid ${resetArm ? "#f4b48a" : COLORS.line}`, background: resetArm ? "rgba(244,180,138,0.15)" : "rgba(4,12,8,0.4)", color: resetArm ? "#f4b48a" : "rgba(244,240,230,0.7)", fontSize: "12px", fontWeight: 600, cursor: "pointer" }}
            >
              {resetArm ? "Tap again to confirm reset -> 00" : "Reset order counter"}
            </button>
            {resetMsg && <div style={{ fontSize: "11.5px", color: "rgba(244,240,230,0.6)", marginTop: "8px" }}>{resetMsg}</div>}
          </div>
          </>
          )}
        </div>

        {/* item detail modal */}
        {selectedItem && (
          <div className="hd-rise-anim" style={{ position: "fixed", inset: 0, zIndex: 30, background: "rgba(4,12,8,0.85)", backdropFilter: "blur(6px)", display: "flex", alignItems: "flex-end" }} onClick={() => setSelectedItem(null)}>
            <div onClick={(e) => e.stopPropagation()} style={{ width: "100%", background: "#0d1f16", borderRadius: "20px 20px 0 0", padding: "22px 22px calc(22px + env(safe-area-inset-bottom))", border: `1px solid ${COLORS.line}` }}>
              <div style={{ display: "flex", alignItems: "center", gap: "12px", marginBottom: "14px" }}>
                <Badge type={selectedItem.item.drinkId} size={48} />
                <div>
                  <div className="hd-display" style={{ fontSize: "26px", fontWeight: 600, color: COLORS.white }}>{selectedItem.item.en}</div>
                  <div style={{ fontSize: "12px", color: "rgba(244,240,230,0.6)" }}>Order {formatOrderNumber(selectedItem.orderNumber)}{selectedItem.name ? ` - ${selectedItem.name}` : ""}</div>
                </div>
              </div>
              <div style={{ fontSize: "14px", color: COLORS.cream, background: "rgba(244,240,230,0.06)", borderRadius: "12px", padding: "12px 14px", marginBottom: "18px" }}>
                {describeItem(selectedItem.item)}
              </div>
              <label style={{ display: "flex", alignItems: "center", gap: "12px", padding: "14px", borderRadius: "12px", border: `1.5px solid ${COLORS.sage}`, background: "rgba(159,230,192,0.1)", cursor: "pointer" }}>
                <input type="checkbox" onChange={() => markItemReady(selectedItem)} style={{ width: "20px", height: "20px", accentColor: COLORS.sage }} />
                <span style={{ fontSize: "14.5px", fontWeight: 700, color: COLORS.white }}>Mark Ready</span>
              </label>
              <button onClick={() => setSelectedItem(null)} style={{ width: "100%", marginTop: "10px", padding: "12px", borderRadius: "12px", border: `1px solid ${COLORS.line}`, background: "transparent", color: "rgba(244,240,230,0.7)", fontSize: "13px", cursor: "pointer" }}>
                Cancel
              </button>
            </div>
          </div>
        )}

        <BottomTabs page={page} setPage={setPage} cartCount={cart.length} />
      </div>
    );
  }

  /* ---------------- Confirmed ---------------- */
  if (page === "confirmed") {
    return (
      <div className="hd-ui" style={{ minHeight: "100vh", width: "100%", color: COLORS.cream, position: "relative" }}>
        <GlobalStyle /><SketchyDefs />
        <BackgroundPhoto src={BG.confirm} />
        <div className="hd-rise-anim" style={{ position: "relative", minHeight: "100vh", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", padding: "24px", textAlign: "center" }}>
          <div style={{ fontSize: "12px", letterSpacing: "0.28em", color: "rgba(244,240,230,0.75)", fontWeight: 600 }}>YOUR ORDER</div>
          {customerName.trim() && <div className="hd-display" style={{ fontSize: "24px", fontStyle: "italic", color: COLORS.gold, marginTop: "8px" }}>for {customerName.trim()}</div>}
          <div className="hd-display" style={{ fontSize: "clamp(80px, 26vw, 130px)", lineHeight: 1, fontWeight: 600, color: COLORS.white, marginTop: "4px", textShadow: "0 0 50px rgba(201,168,118,0.4)" }}>
            {formatOrderNumber(orderNumber)}
          </div>
          <Badge type={primary.id} size={110} />
          <div className="hd-display" style={{ fontSize: "26px", color: COLORS.white, marginTop: "16px" }}>Your {primary.en} is {primary.verb}...</div>
          <div style={{ marginTop: "10px", fontSize: "13px", color: "rgba(244,240,230,0.75)" }}>We'll call your number when it's ready.</div>
          <div style={{ marginTop: "14px", fontSize: "13px", color: COLORS.gold }}>tips are appreciated&gt;_&lt;</div>
          <button onClick={newOrder} className="hd-ui" style={{ marginTop: "30px", padding: "12px 28px", borderRadius: "999px", border: `1px solid ${COLORS.line}`, background: "rgba(4,12,8,0.4)", color: COLORS.cream, fontSize: "13px", fontWeight: 600, cursor: "pointer", backdropFilter: "blur(6px)" }}>
            New Order
          </button>
        </div>
      </div>
    );
  }

  /* ---------------- Individual drink page ---------------- */
  if (currentDrink) {
    const drink = currentDrink;
    const foamOk = drink.foamEligible ? drink.foamEligible(draft) : false;
    return (
      <div className="hd-ui" style={{ minHeight: "100vh", width: "100%", color: COLORS.cream, position: "relative" }}>
        <GlobalStyle /><SketchyDefs />
        <BackgroundPhoto src={BG[drink.id]} />
        <div style={{ position: "relative", minHeight: "100vh", display: "flex", flexDirection: "column" }}>
          <div style={{ padding: "50px 20px 0" }}>
            <button onClick={() => setPage("home")} style={{ background: "rgba(4,12,8,0.4)", border: `1px solid ${COLORS.line}`, borderRadius: "999px", padding: "8px", cursor: "pointer", backdropFilter: "blur(6px)" }}>
              <ArrowLeft size={18} color={COLORS.cream} />
            </button>
          </div>
          <div style={{ flex: 1 }} />
          <div className="hd-rise-anim" style={{ padding: "20px 20px calc(96px + env(safe-area-inset-bottom))" }}>
            <div style={{ display: "flex", alignItems: "center", gap: "14px", marginBottom: "16px" }}>
              <Badge type={drink.id} size={64} />
              <div>
                <div className="hd-display" style={{ fontSize: "34px", fontWeight: 600, lineHeight: 1, color: COLORS.white }}>{drink.en}</div>
                <div style={{ fontSize: "12.5px", color: "rgba(244,240,230,0.75)", marginTop: "4px" }}>{drink.note}</div>
              </div>
            </div>

            {drink.special ? (
              <div style={{ background: "rgba(4,12,8,0.5)", backdropFilter: "blur(10px)", border: `1px solid ${COLORS.line}`, borderRadius: "18px", padding: "18px", display: "flex", flexDirection: "column", gap: "14px" }}>
                <div style={{ fontSize: "13.5px", color: COLORS.cream, fontStyle: "italic" }}>
                  Please ask us about the beans we have today.
                </div>
                <button onClick={() => addToCart(drink)} style={{ padding: "13px", borderRadius: "12px", border: "none", background: COLORS.gold, color: "#241f18", fontSize: "14.5px", fontWeight: 700, cursor: "pointer" }}>
                  Add to Order
                </button>
              </div>
            ) : (
              <div style={{ background: "rgba(4,12,8,0.5)", backdropFilter: "blur(10px)", border: `1px solid ${COLORS.line}`, borderRadius: "18px", padding: "18px", display: "flex", flexDirection: "column", gap: "16px" }}>
                <div>
                  <div style={{ fontSize: "11px", letterSpacing: "0.1em", color: "rgba(244,240,230,0.6)", marginBottom: "9px", fontWeight: 700 }}>TEMPERATURE</div>
                  <div style={{ display: "flex", flexWrap: "wrap", gap: "8px" }}>
                    {drink.temps.map((t) => (
                      <Chip key={t.id} active={draft.temp === t.id} onClick={() => setDraft((d) => ({ ...d, temp: t.id }))}>{t.en}</Chip>
                    ))}
                  </div>
                </div>
                <div>
                  <div style={{ fontSize: "11px", letterSpacing: "0.1em", color: "rgba(244,240,230,0.6)", marginBottom: "9px", fontWeight: 700 }}>FLAVOR</div>
                  <div style={{ display: "flex", flexWrap: "wrap", gap: "8px" }}>
                    {drink.flavors.map((f) => (
                      <Chip key={f.id} active={draft.flavor === f.id} onClick={() => setDraft((d) => ({ ...d, flavor: f.id }))}>{f.en}</Chip>
                    ))}
                  </div>
                </div>
                <div>
                  <div style={{ fontSize: "11px", letterSpacing: "0.1em", color: "rgba(244,240,230,0.6)", marginBottom: "9px", fontWeight: 700 }}>CHOICE OF BASE</div>
                  <div style={{ display: "flex", flexWrap: "wrap", gap: "8px" }}>
                    {drink.bases.map((b) => (
                      <Chip key={b.id} active={draft.base === b.id} onClick={() => setDraft((d) => ({ ...d, base: b.id }))}>{b.en}</Chip>
                    ))}
                  </div>
                </div>
                <div>
                  <div style={{ fontSize: "11px", letterSpacing: "0.1em", color: "rgba(244,240,230,0.6)", marginBottom: "9px", fontWeight: 700 }}>COLD FOAM</div>
                  {foamOk ? (
                    <Chip active={draft.foam} onClick={() => setDraft((d) => ({ ...d, foam: !d.foam }))}>Add Cold Foam</Chip>
                  ) : (
                    <div style={{ fontSize: "11.5px", color: "rgba(244,240,230,0.45)", fontStyle: "italic" }}>
                      Only available on flavored drinks or cold brew.
                    </div>
                  )}
                </div>
                <button onClick={() => addToCart(drink)} style={{ padding: "13px", borderRadius: "12px", border: "none", background: COLORS.gold, color: "#241f18", fontSize: "14.5px", fontWeight: 700, cursor: "pointer" }}>
                  Add to Order
                </button>
              </div>
            )}
          </div>
        </div>
        <BottomTabs page={page} setPage={setPage} cartCount={cart.length} />
      </div>
    );
  }

  /* ---------------- Cart / submitting ---------------- */
  if (page === "cart" || page === "submitting") {
    return (
      <div className="hd-ui" style={{ minHeight: "100vh", width: "100%", color: COLORS.cream, position: "relative" }}>
        <GlobalStyle /><SketchyDefs />
        <BackgroundPhoto src={BG.home} />
        <div style={{ position: "relative", minHeight: "100vh", display: "flex", flexDirection: "column", paddingBottom: "90px" }}>
          <div style={{ padding: "50px 20px 16px", display: "flex", alignItems: "center", gap: "12px" }}>
            <button onClick={() => setPage("home")} disabled={page === "submitting"} style={{ background: "rgba(4,12,8,0.4)", border: `1px solid ${COLORS.line}`, borderRadius: "999px", padding: "8px", cursor: "pointer" }}>
              <ArrowLeft size={18} color={COLORS.cream} />
            </button>
            <div className="hd-display" style={{ fontSize: "28px", fontWeight: 600, color: COLORS.white }}>Your Order</div>
          </div>

          <div style={{ flex: 1, overflowY: "auto", padding: "0 20px" }}>
            {submitError && (
              <div style={{ fontSize: "12.5px", color: COLORS.ink, background: "rgba(201,168,118,0.9)", borderRadius: "12px", padding: "10px 12px", marginBottom: "14px" }}>
                {submitError}
              </div>
            )}
            {cart.length === 0 ? (
              <div style={{ color: "rgba(244,240,230,0.6)", fontSize: "13px", marginTop: "40px", textAlign: "center" }}>Nothing here yet - go pick a drink.</div>
            ) : (
              <>
                <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
                  {cart.map((item) => (
                    <div key={item.key} style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "13px 16px", borderRadius: "14px", background: "rgba(4,12,8,0.45)", border: `1px solid ${COLORS.line}`, backdropFilter: "blur(8px)" }}>
                      <div>
                        <div style={{ fontSize: "15px", fontWeight: 600, color: COLORS.white }}>{item.en}</div>
                        <div style={{ fontSize: "12px", color: "rgba(244,240,230,0.6)", marginTop: "3px" }}>{describeItem(item)}</div>
                      </div>
                      {page === "cart" && (
                        <button onClick={() => removeFromCart(item.key)} style={{ background: "none", border: "none", cursor: "pointer", padding: "6px" }}>
                          <X size={16} color="rgba(244,240,230,0.6)" />
                        </button>
                      )}
                    </div>
                  ))}
                </div>
                <div style={{ marginTop: "20px" }}>
                  <div style={{ fontSize: "11px", letterSpacing: "0.08em", color: "rgba(244,240,230,0.6)", marginBottom: "8px", fontWeight: 700 }}>NAME FOR YOUR ORDER (REQUIRED - ONE PERSON PER ORDER)</div>
                  <input
                    className="hd-name-input"
                    value={customerName}
                    onChange={(e) => setCustomerName(e.target.value)}
                    placeholder="e.g. Millie"
                    disabled={page === "submitting"}
                    style={{ width: "100%", padding: "12px 14px", borderRadius: "12px", border: `1px solid ${COLORS.line}`, background: "rgba(4,12,8,0.4)", color: COLORS.cream, fontSize: "14px", outline: "none" }}
                  />
                </div>
                <div style={{ marginTop: "14px", fontSize: "11.5px", color: "rgba(244,240,230,0.55)", fontStyle: "italic" }}>
                  No changes can be made after submitting. If you'd like to cancel, please check in with us.
                </div>
              </>
            )}
          </div>

          <div style={{ padding: "16px 20px 0" }}>
            <button onClick={submitOrder} disabled={cart.length === 0 || !customerName.trim() || page === "submitting"}
              style={{ width: "100%", padding: "15px", borderRadius: "14px", border: "none", background: (cart.length === 0 || !customerName.trim()) ? "rgba(201,168,118,0.35)" : COLORS.gold, color: "#241f18", fontSize: "15px", fontWeight: 700, cursor: (cart.length === 0 || !customerName.trim() || page === "submitting") ? "default" : "pointer", display: "flex", alignItems: "center", justifyContent: "center", gap: "8px" }}>
              {page === "submitting" ? (<><RotateCcw size={16} className="hd-spinner" /> Sending...</>) : (<><Check size={17} /> Submit Order</>)}
            </button>
          </div>
        </div>
        <BottomTabs page={page} setPage={setPage} cartCount={cart.length} />
      </div>
    );
  }

  /* ---------------- Home ---------------- */
  return (
    <div className="hd-ui" style={{ minHeight: "100vh", width: "100%", color: COLORS.cream, position: "relative" }}>
      <GlobalStyle /><SketchyDefs />

      {!supabaseConfigured && (
        <div style={{ position: "relative", zIndex: 5, padding: "10px 20px", background: COLORS.gold, color: "#241f18", fontSize: "12px", textAlign: "center", fontWeight: 600 }}>
          Supabase isn't configured - orders can't be submitted yet.
        </div>
      )}

      <div style={{ position: "relative", paddingBottom: "90px" }}>
        <div style={{ position: "relative", height: "46vh", minHeight: "300px" }}>
          <div style={{ position: "absolute", inset: 0, backgroundImage: `url(${BG.home})`, backgroundSize: "cover", backgroundPosition: "center" }} />
          <div style={{ position: "absolute", inset: 0, background: "linear-gradient(180deg, rgba(4,12,8,0.25) 0%, rgba(4,12,8,0.15) 45%, #07150f 100%)" }} />
          <div style={{ position: "absolute", left: "24px", right: "24px", bottom: "26px" }}>
            <div className="hd-display" style={{ fontSize: "44px", fontWeight: 600, lineHeight: 1, color: COLORS.white }}>Half Day Cafe</div>
            <div style={{ fontSize: "12px", letterSpacing: "0.14em", color: "rgba(244,240,230,0.8)", marginTop: "8px" }}>{"\u6D6E\u751F\u534A\u65E5 - SLOW BREWS, STILL MOMENTS"}</div>
            <div style={{ width: "34px", height: "2px", background: COLORS.gold, marginTop: "12px" }} />
          </div>
        </div>

        <div style={{ padding: "18px 20px 6px", display: "flex", flexDirection: "column", gap: "12px", background: "#07150f" }}>
          <div style={{ fontSize: "11px", letterSpacing: "0.12em", color: "rgba(244,240,230,0.55)", fontWeight: 700, marginBottom: "2px" }}>TODAY'S MENU</div>
          {DRINKS.map((drink) => (
            <button key={drink.id} onClick={() => openDrink(drink.id)} className="hd-card-btn"
              style={{ display: "flex", alignItems: "center", gap: "14px", textAlign: "left", padding: "14px", borderRadius: "16px", border: `1px solid ${COLORS.line}`, background: "rgba(244,240,230,0.05)", cursor: "pointer" }}>
              <Badge type={drink.id} size={52} />
              <div style={{ flex: 1 }}>
                <div className="hd-display" style={{ fontSize: "21px", fontWeight: 600, color: COLORS.white }}>{drink.en}</div>
                <div style={{ fontSize: "12px", color: "rgba(244,240,230,0.6)", marginTop: "2px" }}>{drink.note}</div>
              </div>
              <ChevronRight size={18} color="rgba(244,240,230,0.5)" />
            </button>
          ))}

          <div style={{ marginTop: "10px", borderRadius: "16px", overflow: "hidden", position: "relative", padding: "20px 18px", background: "rgba(244,240,230,0.04)", border: `1px solid ${COLORS.line}` }}>
            <div className="hd-display" style={{ fontSize: "24px", color: COLORS.white }}>{"\u5077\u5F97\u6D6E\u751F\u534A\u65E5\u95F2"}</div>
            <div style={{ fontSize: "12px", color: "rgba(244,240,230,0.75)", marginTop: "6px", fontStyle: "italic" }}>Steal a half-day of leisure from this busy life</div>
            <div style={{ fontSize: "10.5px", color: "rgba(244,240,230,0.5)", marginTop: "10px", letterSpacing: "0.05em" }}>LIC Entertainment Co. Presents</div>
          </div>
        </div>
      </div>

      <BottomTabs page={page} setPage={setPage} cartCount={cart.length} />
    </div>
  );
}
